# Test different coordinate mappings
def test_mapping(r, c, method_name):
    # Method 1: standard integer division
    lr1 = (r // 5) % 5
    lc1 = (c // 5) % 5

    # Method 2: add 1 before division (1-indexed thinking)
    lr2 = ((r + 1) // 5) - 1  # equivalent to floor((r+1)/5) - 1
    lc2 = ((c + 1) // 5) - 1

    # Method 3: ceiling division minus 1
    import math
    lr3 = math.ceil((r + 1) / 5) - 1
    lc3 = math.ceil((c + 1) / 5) - 1

    return {
        method_name: {'lr': (lr1, lr2, lr3), 'lc': (lc1, lc2, lc3)},
        direct: (r//5 % 5, c//5 % 5)
    }

test_cases = [(1, 12), (6, 2), (6, 22), (16, 2), (21, 12)]
print("Test mappings:")
for r, c in test_cases:
    results = {}
    for name in ['direct', 'method2']:
        if name == 'direct':
            results[name] = {'lr': r//5%5, 'lc': c//5%5}
        else:
            l = (r + 1) // 5 - 1
            c_val = (c + 1) // 5 - 1
